  const stableOnMoveEnd = React.useCallback(() => { onMoveEndRef.current?.(); }, []);
  const stableOnSelectionChange = React.useCallback((selection: OnSelectionChangeParams) => { onSelectionChangeRef.current?.(selection); }, []);

