        </div>
        <Scrollable className="flex-1 min-h-0">
          <div data-slot="side-panel-content" className="p-[10px]">{activeTab && (ActiveTabContent ? <ActiveTabContent /> : (activeTab.content as React.ReactNode))}</div>
