// [👤compose📚js🗃️sketchpad💻elements🔖inputcomponents🔖stepper](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/elements.tsx/s/Input%20Components/s/Stepper)
// Numeric stepper with increment/decrement and drag adjustment.
// Consumers MUST provide min and max bounds.

/**
 * [👤compose📚js🗃️sketchpad💻elements🔖inputcomponents🔖stepper✂️stepperprops](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/elements.tsx/s/Input%20Components/s/Stepper/d/i/StepperProps)
 * StepperProps holds the data fields for a StepperProps record.
 **/
interface StepperProps extends ElementProps {
  value?: number;
  defaultValue?: number;
  min?: number;
  max?: number;
  step?: number;
  onChange?: (value: number) => void;
  onPointerDown?: () => void;
  onPointerUp?: () => void;
  onPointerCancel?: () => void;
  interactionId?: string;
}

/**
 * Numeric stepper with increment, decrement, and drag-to-adjust.
 *
 *  * [👤compose📚js🗃️sketchpad💻elements🔖inputcomponents🔖stepper🪨stepper](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/elements.tsx/s/Input%20Components/s/Stepper/d/i/Stepper)
