 **/
export const kitDiagramNormalizeVector = (vector: KitDiagramPoint): KitDiagramPoint => {
  const length = kitDiagramVectorLength(vector);
  if (length === 0) return { x: 0, y: 0 };
  return { x: vector.x / length, y: vector.y / length };
