/**
 * Computes the dot product of two vectors.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🪨kitdiagramdot](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/kitDiagramDot)
 **/
export const kitDiagramDot = (a: KitDiagramPoint, b: KitDiagramPoint): number => a.x * b.x + a.y * b.y;
/**
 * Computes the squared Euclidean distance between two points.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🪨kitdiagramdistancesquared](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/kitDiagramDistanceSquared)
 **/
export const kitDiagramDistanceSquared = (a: KitDiagramPoint, b: KitDiagramPoint): number => {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return dx * dx + dy * dy;
};
/**
 * Translates a local point to absolute coordinates by adding an origin offset.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🪨kitdiagramtoabsolutepoint](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/kitDiagramToAbsolutePoint)
 **/
export const kitDiagramToAbsolutePoint = (origin: KitDiagramPoint, localPoint: KitDiagramPoint): KitDiagramPoint => ({
  x: origin.x + localPoint.x,
  y: origin.y + localPoint.y,
});
/**
 * Infers the cardinal snap side of a point relative to the frame center.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🪨kitdiagraminfersnapside](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/kitDiagramInferSnapSide)
 **/
export const kitDiagramInferSnapSide = (point: KitDiagramPoint, frame: Partial<KitDiagramFrame>, fallback: KitDiagramFrame = KIT_DIAGRAM_CIRCLE_FRAME): KitDiagramSnapSide => {
  const normalizedFrame = normalizeKitDiagramFrame(frame, fallback);
  const center = kitDiagramCenter(normalizedFrame, fallback);
  const dx = point.x - center.x;
  const dy = point.y - center.y;
  if (Math.abs(dx) > Math.abs(dy)) {
    return dx >= 0 ? "right" : "left";
  }
  return dy >= 0 ? "bottom" : "top";
};

// [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🪨createcirclesnappoints](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/createCircleSnapPoints)
/**
 * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🪨createcirclesnappoints](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/createCircleSnapPoints)
