export const commands = {
  "compose.typeApp.selectConnector": (context: TypeAppCommandContext, connectorGuid: Guid): TypeAppCommandResult => {
    const currentConnectors = context.typeApp.selection?.connectors || [];
    return {
      diff: {
        selection: {
          connectors: { added: [connectorGuid], removed: [] },
        },
      },
    };
  },
  "compose.typeApp.deselectConnector": (context: TypeAppCommandContext, connectorGuid: Guid): TypeAppCommandResult => {
    return {
      diff: {
        selection: {
          connectors: { added: [], removed: [connectorGuid] },
        },
      },
    };
  },
  "compose.typeApp.selectModel": (context: TypeAppCommandContext, reprGuid: Guid): TypeAppCommandResult => {
    return {
      diff: {
