          models: { added: [reprGuid], removed: [] },
        },
      },
    };
  },
  "compose.typeApp.deselectModel": (context: TypeAppCommandContext, reprGuid: Guid): TypeAppCommandResult => {
    return {
      diff: {
        selection: {
          models: { added: [], removed: [reprGuid] },
        },
      },
    };
  },
  "compose.typeApp.hoverPort": (context: TypeAppCommandContext, connectorGuid: Guid): TypeAppCommandResult => {
    return {
      diff: {
        hover: { connector: connectorGuid },
      },
    };
  },
  "compose.typeApp.hoverModel": (context: TypeAppCommandContext, reprGuid: Guid): TypeAppCommandResult => {
    return {
      diff: {
        hover: { model: reprGuid },
      },
    };
  },
  "compose.typeApp.clearHover": (context: TypeAppCommandContext): TypeAppCommandResult => {
    return {
      diff: {
        hover: {},
      },
    };
  },
  "compose.typeApp.setCamera": (context: TypeAppCommandContext, camera: Camera): TypeAppCommandResult => {
    return {
      diff: {
        camera,
      },
    };
  },
  "compose.typeApp.focusPort": (context: TypeAppCommandContext, connectorGuid: Guid): TypeAppCommandResult => {
    return {
      diff: {
        focusedConnectorGuid: connectorGuid,
      },
    };
  },
  "compose.typeApp.clearFocus": (context: TypeAppCommandContext): TypeAppCommandResult => {
    return {
      diff: {
        focusedConnectorGuid: null,
      },
    };
  },
  "compose.typeApp.setActiveTool": (context: TypeAppCommandContext, tool: ToolKind): TypeAppCommandResult => {
    return {
      diff: {
        activeTool: tool,
      },
    };
  },
  "compose.typeApp.togglePanel": (context: TypeAppCommandContext, panel: keyof PanelVisibility): TypeAppCommandResult => {
    return {
      diff: {
        panelVisibility: {
          [panel]: !context.typeApp.panelVisibility[panel],
        },
      },
    };
  },
  "compose.typeApp.deselectAll": (context: TypeAppCommandContext): TypeAppCommandResult => {
    return {
      diff: {
        selection: {
          connectors: { removed: context.typeApp.selection?.connectors || [] },
          models: { removed: context.typeApp.selection?.models || [] },
        },
      },
    };
  },
  "compose.typeApp.selectAll": (context: TypeAppCommandContext): TypeAppCommandResult => {
    const type = context.kit.types?.find((t) => t.guid === context.Guid);
    const allConnectors = type?.connectors?.map((p) => p.guid) || [];
    const allModels = type?.models?.map((r) => r.guid) || [];
    return {
      diff: {
        selection: {
          connectors: { added: allConnectors },
          models: { added: allModels },
        },
      },
    };
  },
  "compose.typeApp.addModelTag": (context: TypeAppCommandContext, tag: string): TypeAppCommandResult => {
    const currentTags = context.typeApp.selectedModelTags || [];
    if (currentTags.includes(tag)) {
      return {};
    }
    return {
      diff: {
        selectedModelTags: [...currentTags, tag],
      },
    };
  },
  "compose.typeApp.removeModelTag": (context: TypeAppCommandContext, tag: string): TypeAppCommandResult => {
    const currentTags = context.typeApp.selectedModelTags || [];
    return {
      diff: {
        selectedModelTags: currentTags.filter((t) => t !== tag),
      },
    };
  },
  "compose.typeApp.clearModelTags": (context: TypeAppCommandContext): TypeAppCommandResult => {
    return {
      diff: {
        selectedModelTags: [],
      },
    };
  },
  "compose.typeApp.setModelTags": (context: TypeAppCommandContext, tags: string[]): TypeAppCommandResult => {
    return {
      diff: {
        selectedModelTags: tags,
      },
    };
