/** ModelsSectionForm holds the data fields for a ModelsSectionForm record.
// [👤compose📚js🗃️sketchpad💻type🔖imports🔖panels🔖right🔖details🪨modelssectionform](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Type.tsx/s/Imports/s/Panels/s/Right/s/Details/d/i/ModelsSectionForm)
/**
 * [👤compose📚js🗃️sketchpad💻type🔖panels🔖right🔖details🪨modelssectionform](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Type.tsx/s/Panels/s/Right/s/Details/d/i/ModelsSectionForm)
 **/
const ModelsSectionForm: FC = () => {
  const tooltip = useTooltip();
  const [hoverModel] = useTypeAppHoverModel();
  const [clearHover] = useTypeAppClearHover();
  const kitCommands = useKitCommands();
  const type = useType(undefined, undefined, true) as Type;
  const [selection, setSelection] = useTypeAppSelection();
  const [hover] = useTypeAppHover();
  const [activeTool] = useTypeAppActiveTool();

  const applyDiff = (diff: any) => {
    kitCommands?.updateType(type.guid, diff);
  };

  const updateModel = (id: string, modelDiff: any) => {
    applyDiff({
      models: {
        updated: [{ id, diff: modelDiff }],
      },
    });
  };

  const hasModels = type.models && type.models.length > 0;

  return (
    <>
      <TreeItem
        id="compose.sketchpad.app.type.models"
        actions={[
          {
            icon: <AddIcon />,
            onClick: () => {
              const origin = "compose.sketchpad.app.type.panel.details.models.add";
              applyDiff({
                models: {
                  added: [{ guid: guid(), url: "", tags: [] }],
                },
              });
            },
            id: "compose.sketchpad.common.add",
          },
        ]}
      >
        {hasModels && (
          <SortableTreeItems
            items={(type.models || []).map((model: any, index: number) => ({
              ...model,
              id: `model-${index}`,
              index,
            }))}
            onReorder={(oldIndex, newIndex) => {
              if (!type.models) return;
              const origin = "compose.sketchpad.app.type.panel.details.models.reorder";
              applyDiff({
                models: {
                  removed: type.models.map((model: any) => model.guid),
                  added: arrayMove(type.models, oldIndex, newIndex),
                },
              });
            }}
          >
            {(model, index) => {
              const isSelected = selection?.models?.includes(model.guid) || false;
              const isHovered = hover?.model === model.guid;
              return (
                <div
                  key={`model-${index}`}
                  onPointerEnter={() => hoverModel && hoverModel(model.guid)}
                  onPointerLeave={() => clearHover && clearHover()}
                  onClick={(e: React.MouseEvent) => {
                    if (!setSelection) return;
                    const compositionKind = resolveSelectionCompositionKind(activeTool, {
                      shiftKey: e.shiftKey,
                      altKey: e.altKey,
                      ctrlKey: e.ctrlKey,
                      metaKey: e.metaKey,
                    });
                    setSelection({
                      ...(selection || {}),
                      models: applySelectionComposition(selection?.models, [model.guid], compositionKind),
                      connectors: compositionKind === "replace" ? [] : (selection?.connectors || []),
                    });
                  }}
                >
                  <TreeItem
                    key={`model-${index}`}
                    id="compose.sketchpad.app.type.model"
                    label={model.url}
                    sortable={true}
                    sortableId={`model-${index}`}
                    isDragHandle={true}
                    className={`${isSelected ? "bg-accent/20" : ""} ${isHovered ? "bg-hover" : ""}`}
                    actions={[
                      {
                        icon: <RemoveIcon />,
                        onClick: () => {
                          const origin = "compose.sketchpad.app.type.panel.details.models.remove";
                          applyDiff({
                            models: {
                              removed: [model.guid],
                            },
                          });
                        },
                        id: "compose.sketchpad.common.remove",
                      },
                    ]}
                  >
                    <TreeRow>
                        <Input
                          id="compose.sketchpad.app.type.panel.details.section.models.url"
                          value={model.url}
                          onChange={(e) => {
                            updateModel(model.guid, { url: e.target.value });
                          }}
                          showLabel
                        />
                      </TreeRow>
                    <TreeRow>
                        <Textarea
                          id="compose.sketchpad.app.type.panel.details.section.models.description"
                          value={model.description || ""}
                          placeholderId="compose.sketchpad.app.type.modelDescriptionPlaceholder.label"
                          onChange={(e) => {
                            updateModel(model.guid, { description: e.target.value });
                          }}
                          showLabel
                        />
                      </TreeRow>
                    <TreeRow>
                        <Input
                          id="compose.sketchpad.app.type.panel.details.section.models.tags"
                          value={(model.tags || []).join(", ")}
                          placeholderId="compose.sketchpad.app.type.modelTagsPlaceholder.label"
                          onChange={(e) => {
                            updateModel(model.guid, {
                              tags: e.target.value
                                .split(",")
                                .map((tag) => tag.trim())
                                .filter((tag) => tag),
                            });
                          }}
                          showLabel
                        />
                      </TreeRow>
                  </TreeItem>
                </div>
              );
            }}
          </SortableTreeItems>
        )}
      </TreeItem>
    </>
  );
};

/**
 * Detail panel section listing all type connectors with inline editing.
 *
 *  * [👤compose📚js🗃️sketchpad💻type🔖imports🔖panels🔖right🔖details🪨connectorslistsection](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Type.tsx/s/Imports/s/Panels/s/Right/s/Details/d/i/ConnectorsListSection)
 **/
export const ConnectorsListSection: FC = () => {
  const isInTypeScope = useIsInTypeScope();
  if (!isInTypeScope) return null;
  return <ConnectorsListSectionForm />;
};

/** ConnectorsListSectionForm holds the data fields for a ConnectorsListSectionForm record.
// [👤compose📚js🗃️sketchpad💻type🔖imports🔖panels🔖right🔖details🪨connectorslistsectionform](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Type.tsx/s/Imports/s/Panels/s/Right/s/Details/d/i/ConnectorsListSectionForm)
/**
 * [👤compose📚js🗃️sketchpad💻type🔖panels🔖right🔖details🪨connectorslistsectionform](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Type.tsx/s/Panels/s/Right/s/Details/d/i/ConnectorsListSectionForm)
 **/
const ConnectorsListSectionForm: FC = () => {
  const tooltip = useTooltip();
  const [hoverPort] = useTypeAppHoverPort();
  const [clearHover] = useTypeAppClearHover();
  const kitCommands = useKitCommands();
  const type = useType(undefined, undefined, true) as Type;
  const [selection, setSelection] = useTypeAppSelection();
  const [hover] = useTypeAppHover();
  const [activeTool] = useTypeAppActiveTool();

  const applyDiff = (diff: any) => {
    kitCommands?.updateType(type.guid, diff);
  };

  const updatePort = (id: string, connectorDiff: any) => {
    const connector = type.connectors?.find((existingConnector) => existingConnector.guid === id);
    const diff: any = { ...connectorDiff };
    if (connector) {
      if (connectorDiff.point) {
        diff.point = {};
        if (connectorDiff.point.x !== undefined) diff.point.x = connectorDiff.point.x - connector.point.x;
        if (connectorDiff.point.y !== undefined) diff.point.y = connectorDiff.point.y - connector.point.y;
        if (connectorDiff.point.z !== undefined) diff.point.z = connectorDiff.point.z - connector.point.z;
      }
      if (connectorDiff.direction) {
        diff.direction = {};
        if (connectorDiff.direction.x !== undefined) diff.direction.x = connectorDiff.direction.x - connector.direction.x;
        if (connectorDiff.direction.y !== undefined) diff.direction.y = connectorDiff.direction.y - connector.direction.y;
        if (connectorDiff.direction.z !== undefined) diff.direction.z = connectorDiff.direction.z - connector.direction.z;
      }
    }
    applyDiff({
      connectors: {
        updated: [{ id, diff }],
      },
    });
  };

  const hasPorts = type.connectors && type.connectors.length > 0;

  return (
    <>
      <TreeItem
        id="compose.sketchpad.app.type.connectors"
        actions={[
          {
            icon: <AddIcon />,
            onClick: () => {
              const origin = "compose.sketchpad.app.type.panel.details.connectors.add";
              applyDiff({
                connectors: {
                  added: [
                    {
                      guid: guid(),
                      t: 0,
                      point: { x: 0, y: 0, z: 0 },
                      direction: { x: 0, y: 0, z: 1 },
                    },
                  ],
                },
              });
            },
            id: "compose.sketchpad.common.add",
          },
        ]}
      >
        {hasPorts && (
          <TreeRow>
            <Ring
              id="compose.sketchpad.app.type.panel.details.section.connectors.ring"
              orbs={(type.connectors || []).map((connector: any) => {
                const isSelected = selection?.connectors?.includes(connector.guid) || false;
                return {
                  id: connector.guid,
                  t: connector.t ?? 0,
                  selected: isSelected,
                  hovered: hover?.connector === connector.guid,
                  disabled: !isSelected,
                };
              })}
              onOrbChange={(orbId, _oldT, newT) => {
                updatePort(orbId, { t: newT });
              }}
              onOrbSelect={(orbId) => {
                if (!setSelection) return;
                setSelection({
                  ...(selection || {}),
                  connectors: [orbId],
                  models: [],
                });
              }}
              onOrbHoverChange={(orbId, hovered) => {
                if (hovered) hoverPort?.(orbId);
                else clearHover?.();
              }}
              showLabel
            />
          </TreeRow>
        )}
        {hasPorts && (
          <SortableTreeItems
            items={(type.connectors || []).map((connector: any, index: number) => ({
              ...connector,
              id: `connector-${index}`,
              index,
            }))}
            onReorder={(oldIndex, newIndex) => {
              if (!type.connectors) return;
              const origin = "compose.sketchpad.app.type.panel.details.connectors.reorder";
              applyDiff({
                connectors: {
                  removed: type.connectors.map((existingConnector: any) => existingConnector.guid),
                  added: arrayMove(type.connectors, oldIndex, newIndex),
                },
              });
            }}
          >
            {(connector, index) => {
              const isSelected = selection?.connectors?.includes(connector.guid) || false;
              const isHovered = hover?.connector === connector.guid;
              const handleClick = (event: React.MouseEvent) => {
                event.stopPropagation();
                if (!setSelection) return;
                const compositionKind = resolveSelectionCompositionKind(activeTool, {
                  shiftKey: event.shiftKey,
                  altKey: event.altKey,
                  ctrlKey: event.ctrlKey,
                  metaKey: event.metaKey,
                });
                setSelection({
                  ...(selection || {}),
                  connectors: applySelectionComposition(selection?.connectors, [connector.guid], compositionKind),
                  models: compositionKind === "replace" ? [] : (selection?.models || []),
                });
              };

              const handleHover = () => {
                if (hoverPort) hoverPort(connector.guid);
              };

              const handleLeave = () => {
                if (clearHover) clearHover();
              };

              return (
                <div onPointerEnter={handleHover} onPointerLeave={handleLeave} onClick={handleClick}>
                  <TreeItem
                    key={`connector-${index}`}
                    id="compose.sketchpad.app.type.connector"
                    label={connector.port}
                    sortable={true}
                    sortableId={`connector-${index}`}
                    isDragHandle={true}
                    className={`cursor-selectable ${isSelected ? "ring-1 ring-[color:var(--active-base)]" : ""} ${isHovered ? "bg-[color:var(--hover-base)]" : ""}`}
                    actions={[
                      {
                        icon: <RemoveIcon />,
                        onClick: () => {
                          const origin = "compose.sketchpad.app.type.panel.details.connectors.remove";
                          applyDiff({
                            connectors: {
                              removed: [connector.guid],
                            },
                          });
                        },
                        id: "compose.sketchpad.common.remove",
                      },
                    ]}
                  >
                    <TreeRow>
                        <Input
                          lazy
                          id="compose.sketchpad.app.type.panel.details.section.connectors.port"
                          value={connector.port || ""}
                          placeholderId="compose.sketchpad.app.type.connectorPortPlaceholder.label"
                          onLazyChange={(value: string) => {
                            updatePort(connector.guid, { port: value });
                          }}
                          showLabel
                        />
                      </TreeRow>
                    <TreeRow>
                        <Textarea
                          lazy
                          id="compose.sketchpad.app.type.panel.details.section.connectors.description"
                          value={connector.description || ""}
                          placeholderId="compose.sketchpad.app.type.connectorDescriptionPlaceholder.label"
                          onLazyChange={(value: string) => {
                            updatePort(connector.guid, { description: value });
                          }}
                          showLabel
                        />
                      </TreeRow>
                    <TreeItem id="compose.sketchpad.app.type.connectorPoint">
                      <TreeRow>
                          <Stepper
                            id="compose.sketchpad.app.type.panel.details.section.connectors.point.x"
                            value={connector.point.x}
                            onChange={(value: number) => {
                              updatePort(connector.guid, { point: { x: value } });
                            }}
                            step={0.1}
                          />
                        </TreeRow>
                      <TreeRow>
                          <Stepper
                            id="compose.sketchpad.app.type.panel.details.section.connectors.point.y"
                            value={connector.point.y}
                            onChange={(value: number) => {
                              updatePort(connector.guid, { point: { y: value } });
                            }}
                            step={0.1}
                          />
                        </TreeRow>
                      <TreeRow>
                          <Stepper
                            id="compose.sketchpad.app.type.panel.details.section.connectors.point.z"
                            value={connector.point.z}
                            onChange={(value: number) => {
                              updatePort(connector.guid, { point: { z: value } });
                            }}
                            step={0.1}
                          />
                        </TreeRow>
                    </TreeItem>
                    <TreeItem id="compose.sketchpad.app.type.connectorDirection">
                      <TreeRow>
                          <Stepper
                            id="compose.sketchpad.app.type.panel.details.section.connectors.direction.x"
                            value={connector.direction.x}
                            onChange={(value: number) => {
                              updatePort(connector.guid, { direction: { x: value } });
                            }}
                            step={0.1}
                          />
                        </TreeRow>
                      <TreeRow>
                          <Stepper
                            id="compose.sketchpad.app.type.panel.details.section.connectors.direction.y"
                            value={connector.direction.y}
                            onChange={(value: number) => {
                              updatePort(connector.guid, { direction: { y: value } });
                            }}
                            step={0.1}
                          />
                        </TreeRow>
                      <TreeRow>
                          <Stepper
                            id="compose.sketchpad.app.type.panel.details.section.connectors.direction.z"
                            value={connector.direction.z}
                            onChange={(value: number) => {
                              updatePort(connector.guid, { direction: { z: value } });
                            }}
                            step={0.1}
                          />
                        </TreeRow>
                    </TreeItem>
                    <TreeRow>
                        <Input
                          lazy
                          id="compose.sketchpad.app.type.panel.details.section.connectors.compatiblePorts"
                          value={(connector.compatiblePorts || []).join(", ")}
                          placeholderId="compose.sketchpad.app.type.connectorCompatiblePortsPlaceholder.label"
                          onLazyChange={(value: string) => {
                            updatePort(connector.guid, {
                              compatiblePorts: value
                                .split(",")
                                .map((port_) => port_.trim())
                                .filter((port_) => port_),
                            });
                          }}
                          showLabel
                        />
                      </TreeRow>
                  </TreeItem>
                </div>
              );
            }}
          </SortableTreeItems>
        )}
      </TreeItem>
    </>
  );
};

