                    id: "compose.sketchpad.common.remove",
                  },
                ]}
              >
                <TreeRow>
                    <Input
                      id="compose.sketchpad.app.type.panel.details.section.authors.name"
                      value={item.name}
                      onChange={(e) => {
                        kitCommands?.updateAuthor(item.guid, { name: e.target.value });
                      }}
                      showLabel
                    />
                  </TreeRow>
                <TreeRow>
                    <Input
                      id="compose.sketchpad.app.type.panel.details.section.authors.email"
                      value={item.email}
                      onChange={(e) => {
                        kitCommands?.updateAuthor(item.guid, { email: e.target.value });
                      }}
                      showLabel
                    />
                  </TreeRow>
              </TreeItem>
            )}
          </SortableTreeItems>
        )}
      </TreeItem>
    </>
  );
};

