/**
 * [👤compose📚js🗃️sketchpad💻type🔖panels🔖right🔖details🪨attributessectionform](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Type.tsx/s/Panels/s/Right/s/Details/d/i/AttributesSectionForm)
 * AttributesSectionForm holds the data fields for a AttributesSectionForm record.
 **/
const AttributesSectionForm: FC = () => {
  const tooltip = useTooltip();
  const kitCommands = useKitCommands();
  const type = useType(undefined, undefined, true) as Type;

  const applyDiff = (diff: any) => {
    kitCommands?.updateType(type.guid, diff);
  };

  const updateAttribute = (id: string, attributeDiff: any) => {
    applyDiff({
      attributes: {
        updated: [{ id, diff: attributeDiff }],
      },
    });
  };

  const hasAttributes = type.attributes && type.attributes.length > 0;

  return (
    <>
      <TreeItem
        id="compose.sketchpad.app.type.attributes"
        actions={[
          {
            icon: <AddIcon />,
            onClick: () => {
              const origin = "compose.sketchpad.app.type.panel.details.attributes.add";
              applyDiff({
                attributes: {
                  added: [{ guid: guid(), key: "" }],
                },
              });
            },
            id: "compose.sketchpad.common.add",
          },
        ]}
      >
        {hasAttributes && (
          <SortableTreeItems
            items={(type.attributes || []).map((attribute: any, index: number) => ({
              ...attribute,
              id: `attribute-${index}`,
              index,
            }))}
            onReorder={(oldIndex, newIndex) => {
              if (!type.attributes) return;
              const origin = "compose.sketchpad.app.type.panel.details.attributes.reorder";
              applyDiff({
                attributes: {
                  removed: type.attributes.map((attribute: any) => attribute.guid),
                  added: arrayMove(type.attributes, oldIndex, newIndex),
                },
              });
            }}
          >
            {(attribute, index) => (
              <TreeItem
                key={`attribute-${index}`}
                id="compose.sketchpad.app.type.attribute"
                label={attribute.key}
                sortable={true}
                sortableId={`attribute-${index}`}
                isDragHandle={true}
                actions={[
                  {
                    icon: <RemoveIcon />,
                    onClick: () => {
                      const origin = "compose.sketchpad.app.type.panel.details.attributes.remove";
                      applyDiff({
                        attributes: {
                          removed: [attribute.guid],
                        },
                      });
                    },
                    id: "compose.sketchpad.common.remove",
                  },
                ]}
              >
                <TreeRow>
                    <Input
                      id="compose.sketchpad.app.type.panel.details.section.attributes.name"
                      value={attribute.key}
                      onChange={(e) => {
                        updateAttribute(attribute.guid, { key: e.target.value });
                      }}
                      showLabel
                    />
                  </TreeRow>
                <TreeRow>
                    <Input
                      id="compose.sketchpad.app.type.panel.details.section.attributes.value"
                      value={attribute.value || ""}
                      placeholderId="compose.sketchpad.app.type.attributeValuePlaceholder.label"
                      onChange={(e) => {
                        updateAttribute(attribute.guid, { value: e.target.value });
                      }}
                      showLabel
                    />
                  </TreeRow>
                <TreeRow>
                    <Input
                      id="compose.sketchpad.app.type.panel.details.section.attributes.definition"
                      value={attribute.definition || ""}
                      placeholderId="compose.sketchpad.app.type.attributeDefinitionPlaceholder.label"
                      onChange={(e) => {
                        updateAttribute(attribute.guid, { definition: e.target.value });
                      }}
                      showLabel
                    />
                  </TreeRow>
              </TreeItem>
            )}
          </SortableTreeItems>
        )}
      </TreeItem>
    </>
  );
};

/**
 * Detail panel section for editing a single selected connector.
 *
 *  * [👤compose📚js🗃️sketchpad💻type🔖imports🔖panels🔖right🔖details🪨connectorsection](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Type.tsx/s/Imports/s/Panels/s/Right/s/Details/d/i/ConnectorSection)
 **/
export const ConnectorSection: FC<{ connectorGuid: Guid }> = ({ connectorGuid }) => {
  const isInTypeScope = useIsInTypeScope();
  if (!isInTypeScope) return null;
  return <ConnectorSectionForm connectorGuid={connectorGuid} />;
