// Geometry and selection utilities for kit diagram interactions.

// #endregion 🔖Header

// #region Imports
// [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖imports](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Imports)
// Imports MUST include icon width constant and kit selection types.

import { ICON_WIDTH } from "../compose";
import type { KitAppSelection } from "./Kit";

// #endregion Imports

// #region Types
// [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖types](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Types)
// Types MUST define selection value extraction for KitAppSelection dimensions.

/**
 * Extracts the element type from an array-valued KitAppSelection dimension.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖types🛠️selectionvalue](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Types/d/i/SelectionValue)
 **/
export type SelectionValue<K extends keyof KitAppSelection> = NonNullable<KitAppSelection[K]> extends (infer T)[] ? T : never;

// #endregion Types

// #region Generic Utilities
// [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖genericutilities](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Generic%20Utilities)
// Generic Utilities MUST provide immutable selection manipulation functions.

/**
 * Adds a value to the specified selection dimension array.
 *
 * MUST return the original selection if the value is already present.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖genericutilities🛠️addtoselection](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Generic%20Utilities/d/i/addToSelection)
 **/
export function addToSelection<K extends keyof KitAppSelection>(selection: KitAppSelection, key: K, value: SelectionValue<K>): KitAppSelection {
  const currentArray = (selection[key] || []) as SelectionValue<K>[];

  if (currentArray.includes(value)) {
    return selection;
  }

  return {
    ...selection,
    [key]: [...currentArray, value],
  };
}

/**
 * Removes a value from the specified selection dimension array.
 *
 * MUST remove the dimension key entirely when the array becomes empty.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖genericutilities🛠️removefromselection](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Generic%20Utilities/d/i/removeFromSelection)
 **/
export function removeFromSelection<K extends keyof KitAppSelection>(selection: KitAppSelection, key: K, value: SelectionValue<K>): KitAppSelection {
  const currentArray = (selection[key] || []) as SelectionValue<K>[];
  const newArray = currentArray.filter((v) => v !== value);

  if (newArray.length === 0) {
    const { [key]: _, ...rest } = selection;
    return rest;
  }

  return {
    ...selection,
    [key]: newArray,
  };
}

/**
 * Toggles a value in the specified selection dimension array.
 *
 * MUST add the value if absent or remove it if present.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖genericutilities🛠️toggleinselection](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Generic%20Utilities/d/i/toggleInSelection)
 **/
export function toggleInSelection<K extends keyof KitAppSelection>(selection: KitAppSelection, key: K, value: SelectionValue<K>): KitAppSelection {
  const currentArray = (selection[key] || []) as SelectionValue<K>[];

  if (currentArray.includes(value)) {
    return removeFromSelection(selection, key, value);
  } else {
    return addToSelection(selection, key, value);
  }
}

/**
 * Replaces an entire selection dimension with the given values.
 *
 * MUST remove the dimension key when values are undefined or empty.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖genericutilities🛠️replaceselectiondimension](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Generic%20Utilities/d/i/replaceSelectionDimension)
 **/
export function replaceSelectionDimension<K extends keyof KitAppSelection>(selection: KitAppSelection, key: K, values: KitAppSelection[K] | undefined): KitAppSelection {
  if (!values || (Array.isArray(values) && values.length === 0)) {
    const { [key]: _, ...rest } = selection;
    return rest;
  }

  return {
    ...selection,
    [key]: values,
  };
}

/**
 * Removes an entire dimension from the selection.
 *
 * MUST return a new selection object without the specified key.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖genericutilities🛠️clearselectiondimension](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Generic%20Utilities/d/i/clearSelectionDimension)
 **/
export function clearSelectionDimension<K extends keyof KitAppSelection>(selection: KitAppSelection, key: K): KitAppSelection {
  const { [key]: _, ...rest } = selection;
  return rest;
}

/**
 * Returns an empty selection with all dimensions cleared.
 *
 * MUST return a new empty KitAppSelection object.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖genericutilities🛠️clearselection](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Generic%20Utilities/d/i/clearSelection)
 **/
export function clearSelection(): KitAppSelection {
  return {};
}

/**
 * Replaces a selection dimension with all available values.
 *
 * MUST delegate to replaceSelectionDimension with the full value list.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖genericutilities🛠️selectallindimension](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Generic%20Utilities/d/i/selectAllInDimension)
 **/
export function selectAllInDimension<K extends keyof KitAppSelection>(selection: KitAppSelection, key: K, allValues: SelectionValue<K>[]): KitAppSelection {
  return replaceSelectionDimension(selection, key, allValues as KitAppSelection[K]);
}

/**
 * Checks whether a value is present in the specified selection dimension.
 *
 * MUST return false when the dimension is undefined or empty.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖genericutilities🛠️isselected](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Generic%20Utilities/d/i/isSelected)
 **/
export function isSelected<K extends keyof KitAppSelection>(selection: KitAppSelection, key: K, value: SelectionValue<K>): boolean {
  const currentArray = (selection[key] || []) as SelectionValue<K>[];
  return currentArray.includes(value);
}

// #endregion Generic Utilities

// #region Kit Diagram Geometry
// [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry)
// Kit Diagram Geometry MUST provide geometry primitives, shape strategies, and anchor resolution.

/**
 * Union of diagram node kind identifiers mapped to shape strategies.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🛠️kitdiagramnodekind](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KitDiagramNodeKind)
 **/
export type KitDiagramNodeKind = "type" | "design" | "quality" | "port" | "tag" | "concept" | "file" | "folder" | "author";
/**
 * Union of supported diagram shape identifiers.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🛠️kitdiagramshapeid](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KitDiagramShapeId)
 **/
export type KitDiagramShapeId = "circle" | "rectangle" | "triangle" | "long-rectangle";
/**
 * Union of cardinal snap sides for anchor point placement.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🛠️kitdiagramsnapside](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KitDiagramSnapSide)
 **/
export type KitDiagramSnapSide = "top" | "right" | "bottom" | "left";

/**
 * Width and height dimensions of a diagram node frame.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🛠️kitdiagramframe](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KitDiagramFrame)
 **/
export interface KitDiagramFrame {
  width: number;
  height: number;
}

/**
 * Two-dimensional coordinate point in diagram space.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🛠️kitdiagrampoint](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KitDiagramPoint)
 **/
export interface KitDiagramPoint {
  x: number;
  y: number;
}

/**
 * Named snap point on a shape boundary with directional side.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🛠️kitdiagramsnappoint](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KitDiagramSnapPoint)
 **/
export interface KitDiagramSnapPoint extends KitDiagramPoint {
  id: string;
  side: KitDiagramSnapSide;
}

/**
 * Optional CSS class and style overrides for shape rendering.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🛠️kitdiagramshaperenderpayload](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KitDiagramShapeRenderPayload)
 **/
export interface KitDiagramShapeRenderPayload {
  className?: string;
  style?: Record<string, string | number>;
}

/**
 * Shape strategy providing frame, snap points, and nearest-point resolution.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🛠️kitdiagramshapestrategy](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KitDiagramShapeStrategy)
 **/
export interface KitDiagramShapeStrategy {
  id: KitDiagramShapeId;
  frame: KitDiagramFrame;
  getRenderPayload: () => KitDiagramShapeRenderPayload;
  getSnapPoints: (frame?: Partial<KitDiagramFrame>) => KitDiagramSnapPoint[];
  resolveNearestPoint: (targetVector: KitDiagramPoint, frame?: Partial<KitDiagramFrame>) => KitDiagramSnapPoint;
}

/**
 * Fully resolved anchor with local and absolute positions on a shape.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🛠️kitdiagramresolvedanchor](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KitDiagramResolvedAnchor)
 **/
export interface KitDiagramResolvedAnchor {
  strategyId: KitDiagramShapeId;
  frame: KitDiagramFrame;
  localPoint: KitDiagramSnapPoint;
  absolutePoint: KitDiagramPoint;
  center: KitDiagramPoint;
}

/**
 * Input parameters for computing diagram node geometry.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🛠️kitdiagramnodegeometryinput](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KitDiagramNodeGeometryInput)
 **/
export interface KitDiagramNodeGeometryInput {
  kind: KitDiagramNodeKind;
  position: KitDiagramPoint;
  frame?: Partial<KitDiagramFrame>;
}

/**
 * Pair of resolved anchors for source and target endpoints of a connection.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🛠️kitdiagramresolvedanchorpair](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KitDiagramResolvedAnchorPair)
 **/
export interface KitDiagramResolvedAnchorPair {
  source: KitDiagramResolvedAnchor;
  target: KitDiagramResolvedAnchor;
}

/**
 * Proximity-based anchor result with distance from a target point.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🛠️kitdiagramproximityanchor](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KitDiagramProximityAnchor)
 **/
export interface KitDiagramProximityAnchor {
  nodeId: string;
  distance: number;
  anchor: KitDiagramResolvedAnchor;
}

/**
 * Scale multiplier applied to icon width for diagram node sizing.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🪨kitdiagramnodescale](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KIT_DIAGRAM_NODE_SCALE)
 **/
export const KIT_DIAGRAM_NODE_SCALE = 2;
/**
 * Base pixel size for diagram nodes derived from icon width and scale.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🪨kitdiagrambasesize](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KIT_DIAGRAM_BASE_SIZE)
 **/
export const KIT_DIAGRAM_BASE_SIZE = ICON_WIDTH * KIT_DIAGRAM_NODE_SCALE;
/**
 * Default frame dimensions for circle-shaped diagram nodes.
 *
 *  * [👤compose📚js🗃️sketchpad💻kitselectionhelper🔖kitdiagramgeometry🪨kitdiagramcircleframe](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/kitSelectionHelper.ts/s/Kit%20Diagram%20Geometry/d/i/KIT_DIAGRAM_CIRCLE_FRAME)
 **/
export const KIT_DIAGRAM_CIRCLE_FRAME: KitDiagramFrame = { width: KIT_DIAGRAM_BASE_SIZE, height: KIT_DIAGRAM_BASE_SIZE };
/**
