// MUST define generic array and selection diff types with apply and inverse operations.

/**
 * Describes added and removed items for an array diff operation.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🔖standardemptyconstants🔖genericdifftypes🛠️arraydiff](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/s/Standard%20Empty%20Constants/s/Generic%20Diff%20Types/d/i/ArrayDiff)
 **/
export interface ArrayDiff<T> {
  added?: T[];
  removed?: T[];
}

/**
 * Maps selection keys to their corresponding array diffs.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🔖standardemptyconstants🔖genericdifftypes🛠️selectiondiff](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/s/Standard%20Empty%20Constants/s/Generic%20Diff%20Types/d/i/SelectionDiff)
 **/
export type SelectionDiff<TSelection extends Record<string, any[]>> = {
  [K in keyof TSelection]?: ArrayDiff<TSelection[K][number]>;
};

/**
 * Inverts an array diff by swapping added and removed items.
 *
 * MUST swap added and removed arrays to produce the inverse diff.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🔖standardemptyconstants🔖genericdifftypes🛠️inversearraydiff](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/s/Standard%20Empty%20Constants/s/Generic%20Diff%20Types/d/i/inverseArrayDiff)
 **/
export function inverseArrayDiff<T>(diff: ArrayDiff<T>): ArrayDiff<T> {
  const inverse: ArrayDiff<T> = {};
  if (diff.added) inverse.removed = diff.added;
  if (diff.removed) inverse.added = diff.removed;
  return inverse;
}

/**
 * Inverts all array diffs within a selection diff.
 *
 * MUST apply inverseArrayDiff to each key in the selection diff.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🔖standardemptyconstants🔖genericdifftypes🛠️inverseselectiondiff](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/s/Standard%20Empty%20Constants/s/Generic%20Diff%20Types/d/i/inverseSelectionDiff)
 **/
export function inverseSelectionDiff<T extends Record<string, ArrayDiff<any>>>(diff: T): T {
  const inverse = {} as T;
  for (const key in diff) {
    if (Object.prototype.hasOwnProperty.call(diff, key)) {
      inverse[key] = inverseArrayDiff(diff[key]) as T[typeof key];
    }
  }
  return inverse;
}

/**
 * Applies an array diff to a current array, removing then adding items.
 *
 * MUST remove items first, then add non-duplicate items.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🔖standardemptyconstants🔖genericdifftypes🛠️applyarraydiff](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/s/Standard%20Empty%20Constants/s/Generic%20Diff%20Types/d/i/applyArrayDiff)
 **/
export function applyArrayDiff<T>(current: T[] | undefined, diff: ArrayDiff<T>): T[] {
  let result = current ? [...current] : [];
  if (diff.removed) result = result.filter((item) => !diff.removed!.includes(item));
  if (diff.added) result = [...result, ...diff.added.filter((item) => !result.includes(item))];
  return result;
}

/**
 * Applies a selection diff to a partial selection state.
 *
 * MUST apply the array diff for each key present in the selection diff.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🔖standardemptyconstants🔖genericdifftypes🛠️applyselectiondiff](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/s/Standard%20Empty%20Constants/s/Generic%20Diff%20Types/d/i/applySelectionDiff)
 **/
export function applySelectionDiff<TSelection extends Record<string, any[]>>(current: Partial<TSelection>, diff: SelectionDiff<TSelection>): Partial<TSelection> {
  const result = { ...current } as Partial<TSelection>;
  for (const key in diff) {
    if (Object.prototype.hasOwnProperty.call(diff, key)) {
      const typedKey = key as keyof TSelection;
      result[typedKey] = applyArrayDiff(current[typedKey], diff[typedKey]!) as TSelection[typeof typedKey];
    }
  }
  return result;
}

