let depth = 0;
const lines = content.split('\n');
// Find where depth first became 1 from 0
for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  const noStrings = line.replace(/\/\/.*/g, '');
  for (const ch of noStrings) {
    if (ch === '{') { depth++; if (depth === 1) {} }
    if (ch === '}') depth--;
  }
  if (i > 100 && depth === 1) {
    console.log('Depth=1 at line', i+1, ':', lines[i].substring(0, 80));
    break;
  }
}
" 2>&1

